-- ============================================================
-- 02_import_competitors_rankings.sql
-- Loads competitors.csv and competitor_rankings.csv (SQL Server / SSMS)
--
-- 1. Copy both CSV files to C:\temp\ on the machine running SQL Server.
-- 2. Run this script after 01_schema_competitors_rankings.sql.
-- 3. Competitors are loaded first because of the foreign key.
--
-- The CSVs come from m3_rankings_extract.py and are UTF-8 without BOM.
-- competitor_rankings.csv has no rank_id column: the identity value is
-- generated by the database.
-- ============================================================

USE tennis_db;
GO

-- Reset the tables in FK order so the script can be re-run
DELETE FROM dbo.competitor_rankings;
DELETE FROM dbo.competitors;
GO

-- ------------------------------------------------------------
-- Competitors
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.competitors_staging', 'U') IS NOT NULL
    DROP TABLE dbo.competitors_staging;
GO

CREATE TABLE dbo.competitors_staging (
    competitor_id VARCHAR(50),
    name          NVARCHAR(100),
    country       NVARCHAR(100),
    country_code  CHAR(3),
    abbreviation  VARCHAR(10)
);
GO

BULK INSERT dbo.competitors_staging
FROM 'C:\temp\competitors.csv'
WITH (
    FORMAT = 'CSV',
    FIRSTROW = 2,
    FIELDQUOTE = '"',
    CODEPAGE = '65001',
    ROWTERMINATOR = '0x0a'
);
GO

INSERT INTO dbo.competitors (competitor_id, name, country, country_code, abbreviation)
SELECT competitor_id, name, country, country_code, abbreviation
FROM dbo.competitors_staging;
GO

DROP TABLE dbo.competitors_staging;
GO

-- ------------------------------------------------------------
-- Competitor_Rankings (rank_id is generated by IDENTITY)
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.competitor_rankings_staging', 'U') IS NOT NULL
    DROP TABLE dbo.competitor_rankings_staging;
GO

CREATE TABLE dbo.competitor_rankings_staging (
    rank                INT,
    movement            INT,
    points              INT,
    competitions_played INT,
    competitor_id       VARCHAR(50)
);
GO

BULK INSERT dbo.competitor_rankings_staging
FROM 'C:\temp\competitor_rankings.csv'
WITH (
    FORMAT = 'CSV',
    FIRSTROW = 2,
    FIELDQUOTE = '"',
    CODEPAGE = '65001',
    ROWTERMINATOR = '0x0a'
);
GO

INSERT INTO dbo.competitor_rankings
    (rank, movement, points, competitions_played, competitor_id)
SELECT rank, movement, points, competitions_played, competitor_id
FROM dbo.competitor_rankings_staging;
GO

DROP TABLE dbo.competitor_rankings_staging;
GO

-- Load summary
SELECT (SELECT COUNT(*) FROM dbo.competitors)         AS competitors,
       (SELECT COUNT(*) FROM dbo.competitor_rankings) AS competitor_rankings;
GO


